  "v4.pillar1.title": { lv: "Latviešu mantojums", en: "Latvian heritage", ru: "Латвийское наследие", pl: "Łotewskie dziedzictwo", uk: "Латвійська спадщина" },
  "v4.pillar1.desc": { lv: "Dažos izstrādājumos izmantojam motīvus, ko iedvesmojuši Latvijas tradicionālie ornamenti.", en: "Some collections draw inspiration from traditional Latvian ornament and pattern.", ru: "В некоторых коллекциях используем мотивы, вдохновлённые традиционными латвийскими орнаментами.", pl: "W wybranych kolekcjach sięgamy po motywy inspirowane tradycyjnymi łotewskimi ornamentami.", uk: "У деяких колекціях використовуємо мотиви, натхненні традиційними латвійськими орнаментами." },
  "v4.pillar2.title": { lv: "Materiāla izvēle", en: "Material choice", ru: "Выбор материала", pl: "Dobór materiałów", uk: "Вибір матеріалу" },
  "v4.pillar2.desc": { lv: "Izvēlamies sastāvu un apdari atbilstoši izstrādājuma funkcijai. Lietošanas nosacījumus norādām pie konkrētās preces.", en: "We choose casting mixes and finishes to suit each design. Check the product page for intended use and care.", ru: "Подбираем составы и покрытия под назначение изделия. Условия использования и ухода указаны в карточке товара.", pl: "Dobieramy mieszanki i wykończenia do funkcji wyrobu. Warunki użytkowania i pielęgnacji znajdziesz przy produkcie.", uk: "Добираємо суміші та покриття відповідно до призначення виробу. Умови використання й догляду зазначені в картці товару." },
  "v4.pillar3.title": { lv: "Veidots ar rokām", en: "Shaped by hand", ru: "Создано руками", pl: "Kształtowane ręcznie", uk: "Створено руками" },
  "v4.pillar3.desc": { lv: "Pēc liešanas virsmas apstrādājam un detaļas pabeidzam ar rokām.", en: "After casting, we refine the surfaces and finish the details by hand.", ru: "После отливки обрабатываем поверхности и доводим детали вручную.", pl: "Po odlaniu opracowujemy powierzchnie i wykańczamy detale ręcznie.", uk: "Після лиття обробляємо поверхні й завершуємо деталі вручну." },
  "v4.pillar4.title": { lv: "Ģimenes darbnīca", en: "Family workshop", ru: "Семейная мастерская", pl: "Rodzinna pracownia", uk: "Сімейна майстерня" },
  "v4.pillar4.desc": { lv: "Strādājam nelielā ģimenes komandā Daugavpilī un veltām uzmanību katram pasūtījumam.", en: "We are a small family team in Daugavpils, making and preparing each order with care.", ru: "Мы — небольшая семейная команда из Даугавпилса. Внимательно относимся к каждому заказу.", pl: "Jesteśmy małym rodzinnym zespołem z Dyneburga. Dbamy o każde zamówienie.", uk: "Ми — невелика сімейна команда з Даугавпілса. Уважно ставимося до кожного замовлення." },

